/**
 * 🔴 **モジュール評価時の `NODE_ENV` を記録するだけの probe（#1132 レビュー 15 周目）。**
 *
 * `csp.test.ts` の「`NODE_ENV` 総当たり」は、モジュールスコープの読みまで届く必要がある
 * （静的 import 済みのモジュールは `NODE_ENV=test` で一度だけ評価されるので、
 * 呼び出し時に値を動かしても届かない）。その**機構自体の下界**として使う ——
 * 「ローダが本当にモジュールを評価し直しているか」「差し替えが評価の瞬間に効いているか」は、
 * 評価時に env を読むモジュールが 1 つ無いと観測できない。
 *
 * 🔴 `src/` には置かない（本番バンドルに入れない）。`tests/` は typecheck の対象だが
 * アプリからは参照されない。
 */
export const NODE_ENV_AT_EVALUATION = process.env.NODE_ENV;
